def le32(value: int) -> bytes:
    return struct.pack("<I", value)


def crc32_bytes(data: bytes) -> bytes:
    return le32(binascii.crc32(data) & 0xFFFFFFFF)


def encode_vli(value: int) -> bytes:
    out = bytearray()
    while value >= 0x80:
        out.append((value & 0x7F) | 0x80)
        value >>= 7
    out.append(value)
    return bytes(out)


def decode_vli(data: bytes, offset: int) -> tuple[int, int]:
    value = 0
    shift = 0
    while True:
        if offset >= len(data):
            raise CorruptDataError()
        byte = data[offset]
        offset += 1
        value |= (byte & 0x7F) << shift
        if not (byte & 0x80):
            return value, offset
        shift += 7
        if shift > 63:
            raise CorruptDataError()


def round_up4(value: int) -> int:
