def get_alias_defaults(program: str) -> tuple[str, bool, bool, str]:
    base = os.path.basename(program)
    operation = "compress"
    stdout = False
    keep = False
    fmt = "auto"
    if base in {"unxz", "unlzma"}:
        operation = "decompress"
    elif base in {"xzcat", "lzcat"}:
        operation = "decompress"
        stdout = True
        keep = True
    if base == "lzma":
        fmt = "lzma"
    return operation, stdout, keep, fmt


def emit_line(stream: BinaryIO, text: str) -> None:
    stream.write(text.encode("utf-8", "strict"))


def print_short_help(program: str) -> None:
