def print_info_memory() -> None:
    total_bytes = read_total_ram_bytes()
    total_mib = total_bytes // (1024 * 1024)
    cpus = os.cpu_count() or 1
    mt_limit = total_bytes // 4
    mt_limit_mib = mt_limit // (1024 * 1024)
    text = (
        "Hardware information:\n"
        f"  Amount of physical memory (RAM):  {total_mib} MiB ({total_bytes} B)\n"
        f"  Number of processor threads:      {cpus}\n"
        "\n"
        "Memory usage limits:\n"
        "  Compression:                      Disabled\n"
        "  Decompression:                    Disabled\n"
