        f"  Default for -T0:                  {mt_limit_mib} MiB ({mt_limit} B)\n"
    )
    emit_line(sys.stdout.buffer, text)


def read_total_ram_bytes() -> int:
    try:
        with open("/proc/meminfo", "r", encoding="ascii") as handle:
            for line in handle:
                if line.startswith("MemTotal:"):
                    parts = line.split()
                    return int(parts[1]) * 1024
    except OSError:
        pass
    return 0


def error_prefix(cfg: Config) -> str:
