    if cfg.quiet >= 1:
        return
    emit_line(sys.stderr.buffer, f"{error_prefix(cfg)}{message}\n")


def print_error(cfg: Config, status: RunStatus, message: str) -> None:
    status.had_error = True
    if cfg.quiet >= 2:
        return
    emit_line(sys.stderr.buffer, f"{error_prefix(cfg)}{message}\n")


def fail_parse(cfg: Config, message: str, suggestion: bool = True) -> int:
    status = RunStatus(had_error=True)
    print_error(cfg, status, message)
    if suggestion and cfg.quiet < 1:
        emit_line(
            sys.stderr.buffer,
            f"{error_prefix(cfg)}Try '{cfg.program} --help' for more information.\n",
        )
    return 1


def parse_non_negative_decimal(value: str) -> int | None:
    if not value or any(ch < "0" or ch > "9" for ch in value):
        return None
    return int(value)


def parse_size(value: str) -> int | None:
    if not value:
        return None
    suffixes = {
        "b": 1,
        "kib": 1024,
        "mib": 1024 ** 2,
        "gib": 1024 ** 3,
        "tib": 1024 ** 4,
        "kb": 1000,
        "mb": 1000 ** 2,
        "gb": 1000 ** 3,
        "tb": 1000 ** 4,
        "k": 1000,
        "m": 1000 ** 2,
        "g": 1000 ** 3,
        "t": 1000 ** 4,
    }
    lower = value.lower()
    for suffix, multiplier in sorted(suffixes.items(), key=lambda item: -len(item[0])):
        if lower.endswith(suffix):
            number = lower[: -len(suffix)]
            parsed = parse_non_negative_decimal(number)
            if parsed is None:
                return None
            return parsed * multiplier
    return parse_non_negative_decimal(lower)


def validate_suffix(value: str) -> bool:
    return bool(value) and "/" not in value and "\x00" not in value


def parse_args(argv: list[str]) -> tuple[Config | None, int | None]:
    operation, stdout_default, keep_default, fmt_default = get_alias_defaults(argv[0])
    cfg = Config(program=argv[0], operation=operation, stdout=stdout_default, keep=keep_default, fmt=fmt_default)
