                cfg.stdout = True
            elif name == "no-sync":
                cfg.no_sync = True
            elif name == "single-stream":
                cfg.single_stream = True
            elif name == "no-sparse":
                cfg.no_sparse = True
            elif name == "ignore-check":
                cfg.ignore_check = True
            elif name == "extreme":
                cfg.extreme = True
            elif name == "quiet":
                cfg.quiet += 1
            elif name == "verbose":
                cfg.verbose += 1
            elif name == "no-warn":
                cfg.no_warn = True
            elif name == "robot":
                cfg.robot = True
            elif name == "help":
                cfg.special_action = "help"
            elif name == "long-help":
                cfg.special_action = "long-help"
            elif name == "version":
                cfg.special_action = "version"
            elif name == "info-memory":
                cfg.special_action = "info-memory"
            elif name in {"format", "check", "threads", "block-size", "suffix"}:
                if not value_provided:
                    if i + 1 >= len(argv):
                        return None, fail_parse(cfg, f"option '--{name}' requires an argument")
                    value = argv[i + 1]
                    i += 1
                if name == "format":
                    if value not in SUPPORTED_FORMATS:
                        return None, fail_parse(cfg, f"{value}: Unknown file format type", suggestion=False)
                    cfg.fmt = value
                elif name == "check":
                    if value not in CHECK_IDS:
                        return None, fail_parse(cfg, f"{value}: Unsupported integrity check type", suggestion=False)
                    cfg.check_name = value
                elif name == "threads":
                    parsed = parse_non_negative_decimal(value)
                    if parsed is None:
                        return None, fail_parse(cfg, f"{value}: Value is not a non-negative decimal integer", suggestion=False)
                    cfg.threads = parsed
                elif name == "block-size":
                    parsed_size = parse_size(value)
                    if parsed_size is None:
                        return None, fail_parse(cfg, f"{value}: Value is not a non-negative decimal integer", suggestion=False)
                    cfg.block_size = parsed_size
                elif name == "suffix":
                    if not validate_suffix(value):
                        return None, fail_parse(cfg, f"{value}: Invalid filename suffix", suggestion=False)
                    cfg.suffix = value
            elif name == "files":
                cfg.files_sources.append((value if value_provided else None, False))
            elif name == "files0":
                cfg.files_sources.append((value if value_provided else None, True))
            elif name in {
                "memlimit-compress",
                "memlimit-decompress",
                "memlimit-mt-decompress",
                "memlimit",
                "block-list",
                "flush-timeout",
                "no-adjust",
            }:
                if name != "no-adjust" and not value_provided:
                    if i + 1 >= len(argv):
                        return None, fail_parse(cfg, f"option '--{name}' requires an argument")
                    i += 1
            else:
                return None, fail_parse(cfg, f"unrecognized option '--{name}'")
            i += 1
            continue

        j = 1
        while j < len(arg):
            opt = arg[j]
            if opt == "z":
                cfg.operation = "compress"
            elif opt == "d":
                cfg.operation = "decompress"
            elif opt == "t":
                cfg.operation = "test"
            elif opt == "l":
                cfg.operation = "list"
            elif opt == "k":
                cfg.keep = True
            elif opt == "f":
                cfg.force = True
            elif opt == "c":
                cfg.stdout = True
            elif opt == "e":
                cfg.extreme = True
            elif opt == "q":
                cfg.quiet += 1
            elif opt == "v":
                cfg.verbose += 1
            elif opt == "Q":
                cfg.no_warn = True
            elif opt == "h":
                cfg.special_action = "help"
            elif opt == "H":
                cfg.special_action = "long-help"
            elif opt == "V":
                cfg.special_action = "version"
            elif opt in "0123456789":
                cfg.preset = int(opt)
            elif opt in {"S", "F", "C", "T", "M"}:
                if j + 1 < len(arg):
                    value = arg[j + 1 :]
                    j = len(arg)
                else:
                    if i + 1 >= len(argv):
                        if opt == "F":
                            return None, fail_parse(cfg, "option '--format' requires an argument")
                        return None, fail_parse(cfg, f"option requires an argument -- '{opt}'")
                    value = argv[i + 1]
                    i += 1
                    j = len(arg)
                if opt == "S":
                    if not validate_suffix(value):
                        return None, fail_parse(cfg, f"{value}: Invalid filename suffix", suggestion=False)
                    cfg.suffix = value
                elif opt == "F":
                    if value not in SUPPORTED_FORMATS:
                        return None, fail_parse(cfg, f"{value}: Unknown file format type", suggestion=False)
                    cfg.fmt = value
                elif opt == "C":
                    if value not in CHECK_IDS:
                        return None, fail_parse(cfg, f"{value}: Unsupported integrity check type", suggestion=False)
